{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Vorozole, the closest analogue, has excellent oral bioavailability with linear dose-proportional pharmacokinetics in postmenopausal women, supporting high F for the triazole-diaryl scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Isavuconazole, which shares the benzonitrile and 1,2,4-triazole motif, has oral bioavailability >98% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Genaconazole, a triazole antifungal, showed 100% absolute bioavailability versus IV in healthy volunteers, supporting essentially complete oral absorption for this class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Voriconazole, another triazole, is well absorbed orally with a bioavailability of about 90% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Fluconazole has >90% absolute oral bioavailability compared with intravenous administration in healthy volunteers, supporting high F for small triazoles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Dapivirine had low oral bioavailability in humans, but it is a structurally distinct NNRTI with low similarity to the query, so this contradictory evidence has limited transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small triazole bearing two p-cyanophenyl groups. The closest analogue vorozole and multiple triazole antifungals (isavuconazole, genaconazole, voriconazole, fluconazole) show high to complete oral bioavailability, while the low-bioavailability NNRTIs are structurally distant and do not override the strong supportive pattern. Prediction: high.",
  "evidence_gaps": [
    "No direct experimental record for the query molecule itself; prediction relies on transferable analogues.",
    "Several records are qualitative ('excellent') rather than numeric absolute F values.",
    "Low-bioavailability analogues have low Morgan similarity and different scaffolds, limiting their relevance."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

